        '<fieldset><legend>Книги Бинго</legend><div class="bingo-toolbar"><button type="button" data-all-books>Все деревенские книги</button></div>'+Object.entries(M.selectableBooks).map(([book,label])=>{
          const item=record.listings.find(listing=>listing.book===book)||{book,status:'active',sources:[],wantedYears:0,wantedSince:'',removedOn:''};
          const own=typeof item.ownSources==='boolean'?item.ownSources:item.sources.length>0&&JSON.stringify([...item.sources].sort())!==JSON.stringify([...sources].sort());
          return '<section class="bingo-listing" data-book="'+book+'"><label class="bingo-check"><input type="checkbox" name="book-'+book+'"'+(record.listings.some(listing=>listing.book===book)?' checked':'')+'><strong>'+label+'</strong></label><div data-listing-fields><div class="bingo-form-grid"><label>Статус в книге<select name="book-status-'+book+'"><option value="active"'+(item.status==='active'?' selected':'')+'>Актуально</option><option value="inactive"'+(item.status==='inactive'?' selected':'')+'>Снят с розыска</option></select></label>'+field('removed-'+book,'Дата снятия',item.removedOn,'date')+'</div><div class="bingo-form-grid" data-book-time>'+field('years-'+book,'Полных лет в этой книге',item.wantedYears,'number','min="0" max="1000" step="1"')+field('since-'+book,'Либо дата начала в этой книге',item.wantedSince,'date')+'</div><details><summary>Собственные источники этой книги</summary><label class="bingo-check"><input type="checkbox" name="own-source-'+book+'"'+(own?' checked':'')+'>Отдельные источники для этой книги</label><div data-own-source-options>'+picker('source-'+book,M.sources,item.sources)+'</div></details><output data-book-price></output></div></section>';
        }).join('')+'</fieldset>'+
        ['death','capture'].map((kind)=>'<fieldset data-event="'+kind+'"><legend>'+(kind==='death'?'Гибель':'Захват')+'</legend><div class="bingo-form-grid">'+field(kind+'-by',kind==='death'?'Кем убит':'Кем захвачен',record[kind].by,'text','maxlength="160"')+field(kind+'-date','Игровая дата',record[kind].date,'date')+field(kind+'-episode','Ссылка на эпизод',record[kind].episode||'','url')+'</div><p>Принадлежность '+(kind==='death'?'убийц':'захвативших')+'</p>'+picker(kind+'-affiliations',{...M.villages,akatsuki:'Акацуки',free:'Вольные шиноби'},record[kind].affiliations||[record[kind].affiliation||'free'])+'</fieldset>').join('')+
        '<div class="bingo-toolbar"><button class="bingo-primary" type="submit">Сохранить на сервер</button><button type="button" data-bingo-cancel>Закрыть</button></div><p data-bingo-save-status role="status"></p></form>';
      const form=host.querySelector('form');
